// src/data/techFacts.ts — Dashboard'da her açılışta rastgele gösterilen teknik
// bilgi/ipucu bankası. Portalın kapsadığı teknolojilere göre gruplanmıştır:
// JVM, Kubernetes/OpenShift, Ansible/AWX, Dynatrace/Instana (APM), Linux/network,
// log analizi, genel sistem yönetimi ve yapay zeka okur-yazarlığı.

export type TechFactCategory = "efsane-gercek" | "az-bilinen" | "pratik-trick" | "sik-sorun";

export interface TechFact {
  id: string;
  category: TechFactCategory;
  title: string;
  body: string;
  accent?: string;
  spotlight?: string;
}

export const CATEGORY_LABELS: Record<TechFactCategory, string> = {
  "efsane-gercek": "Efsane mi, Gerçek mi?",
  "az-bilinen": "Az Bilinen",
  "pratik-trick": "Pratik Trick",
  "sik-sorun": "Sık Karşılaşılan",
};

const baseTechFacts: TechFact[] = [
  // ── JVM / Java / Heap / GC ────────────────────────────────────────────────
  { id: "jvm-01", category: "efsane-gercek", title: "\"Xmx ne kadar büyükse o kadar hızlı olur\" — YANLIŞ", body: "Aşırı büyük heap, Full GC duraklamalarını daha da uzatabilir çünkü GC'nin taraması gereken alan büyür. Doğru boyutlandırma; uygulamanın gerçek çalışan set (working set) büyüklüğüne, GC algoritmasına ve kabul edilebilir duraklama süresine göre yapılır." },
  { id: "jvm-02", category: "az-bilinen", title: "jstat -gcutil tek satırda tüm GC özetini verir", body: "`jstat -gcutil <pid> 1000` komutu Eden/Survivor/Old/Metaspace kullanım yüzdelerini ve toplam GC sayısı/süresini saniyede bir güncelleyerek gösterir — heap dump almadan hızlı bir sağlık kontrolü için idealdir." },
  { id: "jvm-03", category: "pratik-trick", title: "OutOfMemoryError anında otomatik heap dump alın", body: "`-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/path/to/dumps` JVM parametreleriyle, OOM anında JVM kendiliğinden bir .hprof dosyası üretir — sorunu yeniden üretmeye çalışmadan analiz edebilirsiniz." },
  { id: "jvm-04", category: "sik-sorun", title: "Container içinde JVM, host'un tüm RAM'ini görebilir", body: "Eski JVM sürümlerinde (Java 8u191 öncesi) `-XX:+UseContainerSupport` yoksa JVM, cgroup limitini değil host'un toplam belleğini baz alarak varsayılan heap boyutu hesaplar — bu da container OOMKilled hatalarına yol açar." },
  { id: "jvm-05", category: "az-bilinen", title: "G1GC varsayılan koleksiyoncudur (Java 9+)", body: "Java 9'dan itibaren Parallel GC yerine G1 (Garbage First) varsayılan olmuştur; büyük heap'lerde daha öngörülebilir duraklama süreleri hedefler (`-XX:MaxGCPauseMillis` ile ayarlanabilir)." },
  { id: "jvm-06", category: "efsane-gercek", title: "\"System.gc() çağırmak GC'yi garanti tetikler\" — YANLIŞ", body: "`System.gc()` yalnızca JVM'e bir ÖNERİDİR, garanti değildir. JVM bu isteği tamamen yok sayabilir; production kodunda elle GC tetiklemek anti-pattern kabul edilir." },
  { id: "jvm-07", category: "pratik-trick", title: "jmap ile canlı sistemde heap histogramı", body: "`jmap -histo:live <pid>` komutu, uygulamayı durdurmadan (kısa bir GC tetikleyerek) en çok bellek tüketen sınıfları sayı ve boyuta göre sıralar — memory leak avcılığında ilk adımdır." },
  { id: "jvm-08", category: "az-bilinen", title: "Metaspace, PermGen'in yerini aldı (Java 8+)", body: "Java 8'den itibaren sınıf metadata'sı artık heap dışında, native bellekte (Metaspace) tutulur ve varsayılan olarak sınırsızdır — `-XX:MaxMetaspaceSize` ile sınırlanmazsa class-loader sızıntıları tüm sistem belleğini tüketebilir." },
  { id: "jvm-09", category: "sik-sorun", title: "Yüksek CPU + düşük throughput = GC thrashing olabilir", body: "Heap sürekli dolup boşalıyor ve GC arka arkaya tetikleniyorsa (\"GC thrashing\"), CPU kullanımı yüksek görünür ama uygulama iş yapmıyor gibi hisseder — `jstat -gc` ile GC sıklığı kontrol edilmeli." },
  { id: "jvm-10", category: "pratik-trick", title: "Thread dump ile deadlock tespiti", body: "`jstack <pid>` çıktısının sonunda \"Found one Java-level deadlock\" satırı varsa, ilgili thread'lerin kilit (lock) zincirini doğrudan gösterir — üç kez art arda alınan thread dump, donan thread'leri de ortaya çıkarır." },
  { id: "jvm-11", category: "az-bilinen", title: "Survivor space'ler arasında \"ping-pong\" olur", body: "Genç nesil (young generation) GC'sinde nesneler Eden'den S0'a, sonra S1'e taşınır (kopya-hayatta-kalma). Bu ping-pong belirli bir yaşa (`-XX:MaxTenuringThreshold`) ulaşana kadar sürer, sonra Old generation'a terfi eder." },
  { id: "jvm-12", category: "efsane-gercek", title: "\"-server modu her zaman daha hızlıdır\" — ARTIK GEÇERSİZ", body: "64-bit JVM'lerde client/server modu ayrımı kaldırıldı; modern JVM'ler otomatik olarak sunucu sınıfı optimizasyonlar uygular, `-server` bayrağı artık sessizce yok sayılır." },
  { id: "jvm-13", category: "sik-sorun", title: "ClassNotFoundException ile NoClassDefFoundError farklıdır", body: "İlki, sınıf hiç bulunamadığında (classpath eksik) atılır; ikincisi ise sınıf DERLEME zamanında vardı ama ÇALIŞMA zamanında yüklenemedi (örn. statik başlatıcıda hata fırlatıldı) anlamına gelir — kök neden genelde ilk yüklemedeki gizli bir istisnadır." },
  { id: "jvm-14", category: "pratik-trick", title: "Async-profiler ile production'da düşük overhead profiling", body: "JMX/JConsole yerine `async-profiler` gibi araçlar, JVM safepoint bias'ı olmadan CPU/allocation flame graph'ları üretir — production ortamında güvenle kısa süreli profil almak için tercih edilir." },
  { id: "jvm-15", category: "az-bilinen", title: "String.intern() heap'te ayrı bir havuz kullanır", body: "String constant pool, Java 7'den itibaren PermGen/Metaspace'ten heap'e taşındı — bu da `intern()` ile oluşturulan büyük string havuzlarının artık normal GC'ye tabi olduğu anlamına gelir." },
  { id: "jvm-16", category: "sik-sorun", title: "WildFly/JBoss'ta standalone.xml heap ayarı unutuluyor", body: "JVM heap parametreleri genelde `standalone.conf` (Linux) veya servis unit dosyasında tanımlanır, `standalone.xml`'de DEĞİL — yanlış dosyada arama yapmak en sık zaman kaybı sebebidir." },
  { id: "jvm-17", category: "pratik-trick", title: "GC log'larını insan-okunur analiz etmek için GCViewer/GCEasy", body: "`-Xlog:gc*:file=gc.log` ile toplanan ham GC logları, GCEasy.io veya GCViewer gibi araçlara yüklenerek duraklama dağılımı, throughput ve heap trendleri görsel şekilde incelenebilir." },
  { id: "jvm-18", category: "az-bilinen", title: "Direct (off-heap) buffer'lar heap dump'ta görünmez", body: "`ByteBuffer.allocateDirect()` ile ayrılan bellek native heap'te durur; `jmap -heap` normal heap kullanımını gösterir ama bu native alanı yakalamaz — native memory leak'leri NMT (`-XX:NativeMemoryTracking`) ile izlenmelidir." },
  { id: "jvm-19", category: "efsane-gercek", title: "\"Daha fazla thread = daha hızlı\" — DOĞRU DEĞİL her zaman", body: "CPU çekirdek sayısını aşan thread sayısı, context-switch maliyetini artırır ve throughput'u DÜŞÜREBİLİR — thread pool boyutu iş yüküne (I/O-bound vs CPU-bound) göre ayarlanmalıdır." },
  { id: "jvm-20", category: "sik-sorun", title: "\"Connection refused\" her zaman uygulamanın çöktüğü anlamına gelmez", body: "Port dinleniyor ama backlog kuyruğu dolmuşsa veya güvenlik duvarı reddediyorsa da aynı hata görülür — `ss -tlnp` ile portun gerçekten dinlendiğini doğrulamak ilk adımdır." },

  // ── Kubernetes / OpenShift ────────────────────────────────────────────────
  { id: "k8s-01", category: "az-bilinen", title: "Pod'un yeniden başlaması IP'sini değiştirir", body: "Kubernetes'te Pod IP'leri kalıcı değildir; bir Pod yeniden zamanlandığında (reschedule) yeni bir IP alır. Bu yüzden servisler asla doğrudan Pod IP'sine değil, Service (ClusterIP) üzerinden erişilmelidir." },
  { id: "k8s-02", category: "efsane-gercek", title: "\"Restart eden pod her zaman hatalıdır\" — YANLIŞ", body: "CrashLoopBackOff bazen liveness probe'un çok agresif zaman aşımı ayarından kaynaklanır — uygulama aslında sağlıklı ama probe süresi yetersizdir. `oc describe pod` üzerindeki Events kısmı gerçek nedeni gösterir." },
  { id: "k8s-03", category: "pratik-trick", title: "oc get pods -o wide ile node dağılımını gör", body: "`-o wide` bayrağı, Pod'ların hangi node'da çalıştığını ve Pod IP'sini de tek satırda gösterir — node-bazlı sorun izole ederken `-l app=<label>` ile birlikte kullanmak hızlıdır." },
  { id: "k8s-04", category: "sik-sorun", title: "ImagePullBackOff genelde registry kimlik doğrulaması sorunudur", body: "Image adı doğru olsa bile, node'un private registry'e erişim izni (imagePullSecrets) yoksa bu hata alınır — `oc describe pod` içindeki Events \"unauthorized\" veya \"pull access denied\" mesajını gösterir." },
  { id: "k8s-05", category: "az-bilinen", title: "Namespace'ler arası varsayılan ağ izolasyonu YOKTUR", body: "Aksi belirtilmedikçe (NetworkPolicy tanımlanmadıkça) bir namespace'teki Pod, başka bir namespace'teki Pod'a serbestçe erişebilir — \"izole edilmiş\" varsayımı güvenlik denetimlerinde sık yapılan bir hatadır." },
  { id: "k8s-06", category: "pratik-trick", title: "kubectl/oc rollout undo ile anlık geri alma", body: "`oc rollout undo deployment/<isim>` komutu, bir deployment'ı bir önceki ReplicaSet'e saniyeler içinde geri döndürür — hatalı bir sürümü hızlıca geri almak için manuel image değişikliğinden çok daha hızlıdır." },
  { id: "k8s-07", category: "efsane-gercek", title: "\"Readiness ve Liveness probe aynı şeydir\" — YANLIŞ", body: "Liveness probe başarısız olursa container YENİDEN BAŞLATILIR; readiness probe başarısız olursa Pod sadece Service'in trafik listesinden ÇIKARILIR ama yeniden başlatılmaz. İkisini karıştırmak gereksiz restart döngülerine yol açar." },
  { id: "k8s-08", category: "az-bilinen", title: "ResourceQuota olmayan namespace'te tek bir Pod tüm node'u tüketebilir", body: "CPU/memory `limits` tanımlanmamış bir Pod, node üzerindeki tüm kaynağı kullanabilir ve aynı node'daki diğer Pod'ları \"noisy neighbor\" etkisiyle etkileyebilir." },
  { id: "k8s-09", category: "sik-sorun", title: "Pending durumundaki Pod genelde kaynak veya scheduling kısıtı yüzündendir", body: "`oc describe pod` çıktısındaki \"0/5 nodes are available\" gibi mesajlar; yetersiz CPU/bellek, taint/toleration uyuşmazlığı veya nodeSelector'ın hiçbir node ile eşleşmemesinden kaynaklanır." },
  { id: "k8s-10", category: "pratik-trick", title: "oc get events --sort-by=.lastTimestamp ile kronolojik olay akışı", body: "Tek tek Pod açıklamalarına bakmak yerine, tüm namespace'teki olayları zaman sırasına göre tek komutla listelemek, kısa süre önce ne değiştiğini hızlıca ortaya çıkarır." },
  { id: "k8s-11", category: "az-bilinen", title: "ConfigMap/Secret değişikliği çalışan Pod'a otomatik yansımaz", body: "Bir ConfigMap volume olarak mount edilmişse (ve subPath kullanılmamışsa) dosya içeriği belirli bir gecikmeyle güncellenir, ama ortam değişkeni (env) olarak enjekte edilmişse Pod YENİDEN BAŞLATILMADAN asla güncellenmez." },
  { id: "k8s-12", category: "efsane-gercek", title: "\"Daha fazla replica her zaman daha yüksek erişilebilirlik demektir\" — Kısmen doğru", body: "Tüm replica'lar aynı node'a veya aynı availability zone'a zamanlanmışsa, o node/zone çökünce hepsi birden gider — gerçek yüksek erişilebilirlik için podAntiAffinity ile replica'ları farklı node/zone'lara dağıtmak gerekir." },
  { id: "k8s-13", category: "sik-sorun", title: "\"Error: ErrImagePull\" ile \"ImagePullBackOff\" ardışık gelir", body: "İlki ilk deneme hatasını, ikincisi ise Kubernetes'in üstel gecikmeyle (exponential backoff) tekrar denediğini gösterir — sorunu asıl \"ErrImagePull\" satırındaki alt mesaj açıklar." },
  { id: "k8s-14", category: "pratik-trick", title: "oc rsh ile canlı container'a doğrudan shell", body: "`oc rsh <pod-adı>` komutu, ayrı bir debug pod'u oluşturmadan çalışan container içine kabuk açar — hızlı tanılama için `oc exec -it <pod> -- /bin/sh` alternatifiyle aynı işi görür." },
  { id: "k8s-15", category: "az-bilinen", title: "HPA (Horizontal Pod Autoscaler) varsayılan olarak yalnızca CPU'ya bakar", body: "Bellek veya özel metriklere göre otomatik ölçeklendirme için `metrics-server` yeterli değildir — Prometheus Adapter gibi ek bir metrik kaynağı gerekir." },
  { id: "k8s-16", category: "sik-sorun", title: "PVC \"Pending\" kalması genelde uygun StorageClass eksikliğidir", body: "Talep edilen erişim modu (ReadWriteMany gibi) mevcut StorageClass tarafından desteklenmiyorsa PersistentVolumeClaim sonsuza kadar Pending'de kalır — `oc get storageclass` ile desteklenen modlar kontrol edilmeli." },
  { id: "k8s-17", category: "pratik-trick", title: "oc get pod -o yaml ile tam spec'i dump etmek", body: "Bir Pod'un neden belirli bir node'a zamanlandığını veya hangi tolerasyonlara sahip olduğunu anlamak için ham YAML çıktısı, `describe`'dan daha fazla ayrıntı (özellikle status.conditions) sunar." },
  { id: "k8s-18", category: "efsane-gercek", title: "\"OpenShift, Kubernetes'ten tamamen farklı bir sistemdir\" — YANLIŞ", body: "OpenShift, Kubernetes'in üzerine kurulu bir dağıtımdır (distribution) — `oc` komutları çoğunlukla `kubectl` ile bire bir eşlenir, ek olarak Route, BuildConfig, ImageStream gibi OpenShift'e özgü kaynaklar sunar." },
  { id: "k8s-19", category: "az-bilinen", title: "Init container'lar ana container'dan ÖNCE, sırayla çalışır", body: "Birden fazla init container tanımlanmışsa hepsi paralel değil, tanımlanma sırasına göre BİRER BİRER ve her biri başarıyla tamamlanana kadar bir sonraki başlamaz." },
  { id: "k8s-20", category: "pratik-trick", title: "Label selector ile hızlı filtreleme", body: "`oc get pods -l environment=prod,tier=backend` gibi çoklu label seçiciler, büyük namespace'lerde manuel grep yapmadan doğru Pod grubuna doğrudan ulaşmayı sağlar." },

  // ── Ansible / AWX ─────────────────────────────────────────────────────────
  { id: "awx-01", category: "efsane-gercek", title: "\"command modülü shell komutlarını çalıştırır\" — YANLIŞ", body: "`ansible.builtin.command` modülü BİR SHELL BAŞLATMAZ; `||`, `|`, `>`, ortam değişkeni genişletme gibi hiçbir shell operatörünü desteklemez. Bunlara ihtiyaç varsa `ansible.builtin.shell` kullanılmalıdır." },
  { id: "awx-02", category: "az-bilinen", title: "changed_when: false, idempotency'yi garanti etmez", body: "Bu sadece görev raporunda \"changed\" yerine \"ok\" gösterilmesini sağlar — görevin GERÇEKTEN sistem durumunu değiştirip değiştirmediğiyle ilgili bir kontrol mekanizması değildir, salt-okunur task'larda görsel netlik için kullanılır." },
  { id: "awx-03", category: "pratik-trick", title: "--check --diff ile canlıya dokunmadan önizleme", body: "`ansible-playbook --check --diff` bir playbook'un neyi değiştireceğini gerçekten uygulamadan gösterir — production'da çalıştırmadan önce \"kuru çalıştırma\" (dry-run) alışkanlığı hataları önler." },
  { id: "awx-04", category: "sik-sorun", title: "ignore_errors: true, playbook'u BAŞARISIZ olarak işaretlemeye devam eder", body: "Bu ayar sadece sonraki görevlerin ÇALIŞMAYA DEVAM etmesini sağlar — playbook'un genel çıkış kodu ve AWX job durumu yine de \"failed\" (kısmi) olarak görünebilir, bu bir bug değildir." },
  { id: "awx-05", category: "az-bilinen", title: "hosts: localhost + connection: local, SSH'ı tamamen atlar", body: "AWX Execution Environment üzerinde doğrudan çalıştırılan (jump/bastion host gerektirmeyen) görevlerde bu ikili, gereksiz SSH round-trip'ini ortadan kaldırarak playbook'u hızlandırır." },
  { id: "awx-06", category: "pratik-trick", title: "ansible-lint --profile production ile kurumsal standart denetimi", body: "Varsayılan lint profili yalnızca temel hataları yakalar; `production` profili modül kullanım kalıpları (örn. systemctl yerine service modülü) gibi daha katı kuralları da zorunlu kılar." },
  { id: "awx-07", category: "efsane-gercek", title: "\"become: true her zaman root yapar\" — Tam doğru değil", body: "`become` yalnızca yetki YÜKSELTME MEKANİZMASINI etkinleştirir; hedef kullanıcı `become_user` ile herhangi biri olabilir (root olması gerekmez), ve sudoers politikası izin vermezse görev yine başarısız olur." },
  { id: "awx-08", category: "sik-sorun", title: "\"UNREACHABLE\" hatası her zaman host'un kapalı olduğu anlamına gelmez", body: "SSH anahtar uyuşmazlığı, yanlış kullanıcı adı, host_key_checking veya bastion/jump host zinciri sorunları da aynı hatayı üretir — `ansible -m ping` ile izole test, gerçek sebebi ayırt eder." },
  { id: "awx-09", category: "az-bilinen", title: "AWX'te extra_vars, survey'den gelen değerleri ezebilir", body: "Job Template'te sabit tanımlanan extra_vars, kullanıcı bir Survey aracılığıyla farklı bir değer girse bile önceliğe sahip olabilir — değişken önceliği (precedence) sırası dikkatle kontrol edilmelidir." },
  { id: "awx-10", category: "pratik-trick", title: "handlers yalnızca notify edildiklerinde VE playbook sonunda bir kez çalışır", body: "Bir handler, playbook içinde 10 farklı görevden notify edilse bile YALNIZCA BİR KEZ (ve tüm görevler bittikten sonra) tetiklenir — bu, örneğin bir servisi 10 kez değil 1 kez yeniden başlatmayı sağlar." },
  { id: "awx-11", category: "efsane-gercek", title: "\"Ansible bir programlama dilidir\" — YANLIŞ", body: "Ansible bildirimsel (declarative) bir otomasyon aracıdır, Turing-complete bir dil değildir — karmaşık koşullu mantık için Jinja2 filtrelerine aşırı güvenmek yerine genelde modüler roller/playbook'lar tercih edilir." },
  { id: "awx-12", category: "az-bilinen", title: "serial: ile rolling update yapılabilir", body: "`serial: 2` gibi bir ayar, playbook'u tüm hostlara aynı anda değil, gruplar halinde (örn. ikişer ikişer) uygular — bu, bir dağıtımda TÜM sunucuların aynı anda etkilenmesini önleyen basit bir canary/rolling stratejisidir." },
  { id: "awx-13", category: "sik-sorun", title: "Jinja2 şablonunda boşluk/tab hatası sessiz kalabilir", body: "`{{ variable }}` içinde yanlış bir değişken adı, hata fırlatmak yerine bazen boş string üretir (`undefined` filtresi ayarına bağlı) — beklenmedik boş çıktı, genelde yazım hatasına işaret eder." },
  { id: "awx-14", category: "pratik-trick", title: "AWX job çıktısını API üzerinden JSON olarak çekmek", body: "`/api/v2/jobs/<id>/stdout/?format=json` uç noktası, ham stdout yerine yapılandırılmış (task bazlı) çıktı sağlar — otomasyon/entegrasyonlarda regex ile ekran kazımaktan çok daha güvenilirdir." },
  { id: "awx-15", category: "az-bilinen", title: "Vault ile şifrelenen dosyalar git'e güvenle commit edilebilir", body: "`ansible-vault encrypt` ile şifrelenmiş bir değişken dosyası, decrypt anahtarı olmadan anlamsız bir metindir — bu sayede sırlar (secrets) version control'e dahi güvenle eklenebilir (yine de ayrı bir secret store önerilir)." },

  // ── Dynatrace / Instana / APM ─────────────────────────────────────────────
  { id: "apm-01", category: "efsane-gercek", title: "\"APM aracı otomatik olarak tüm sorunları çözer\" — YANLIŞ", body: "Dynatrace/Instana gibi araçlar sorunları TESPİT EDER ve KÖK NEDENİ işaret etmeye YARDIMCI OLUR — düzeltme (fix) her zaman insan/otomasyon müdahalesi gerektirir, araç kendiliğinden kod veya altyapı değiştirmez." },
  { id: "apm-02", category: "az-bilinen", title: "Dynatrace'in Davis AI'ı korelasyon bulur, ille de nedensellik değil", body: "Aynı anda birden fazla anormallik tespit edildiğinde AI bunları ilişkilendirebilir, ama gerçek kök nedenin hangisi olduğunu doğrulamak yine mühendisin işidir — \"Davis dedi\" tek başına kanıt değildir." },
  { id: "apm-03", category: "pratik-trick", title: "Instana'da \"Unbounded\" trace'leri filtrelemek gürültüyü azaltır", body: "Çok uzun süren veya çok fazla span içeren trace'ler dashboard'u yavaşlatabilir — belirli bir süre/span eşiğiyle filtreleme, gerçek sorunlu istekleri bulmayı hızlandırır." },
  { id: "apm-04", category: "sik-sorun", title: "\"Response time arttı\" alarmı her zaman uygulama hatası değildir", body: "Ağ gecikmesi, DNS çözümleme yavaşlığı, downstream bağımlılık (üçüncü parti API) veya veritabanı kilitlenmesi de aynı semptomu üretir — APM'nin \"Service Flow\"/dağıtık iz (trace) görünümü asıl darboğazı gösterir." },
  { id: "apm-05", category: "az-bilinen", title: "OneAgent (Dynatrace) kod değişikliği olmadan enjekte olur", body: "Dynatrace'in ajanı, uygulama kodunu değiştirmeden bytecode enstrümantasyonu ile çalışır — bu \"kod değişikliği gerektirmeyen\" gözlemlenebilirlik (observability) yaklaşımının temelidir." },
  { id: "apm-06", category: "efsane-gercek", title: "\"Yeşil dashboard = her şey yolunda\" — Yanıltıcı olabilir", body: "Bir metrik eşiği aşmadıysa dashboard yeşil görünür, ama eşiğin kendisi yanlış ayarlanmış olabilir (örn. çok yüksek bir CPU alarmı hiç tetiklenmez) — eşik/baseline periyodik olarak gözden geçirilmelidir." },
  { id: "apm-07", category: "pratik-trick", title: "Baseline (temel çizgi) sapması, sabit eşikten daha güvenilirdir", body: "Sabit bir \"CPU > %80\" alarmı yerine, geçmiş davranışa göre dinamik sapma tabanlı alarm (anomaly detection), günün farklı saatlerindeki normal trafik dalgalanmalarını yanlışlıkla alarm olarak işaretlemez." },
  { id: "apm-08", category: "az-bilinen", title: "Distributed tracing'de \"span\" tek bir işlemi, \"trace\" tüm yolculuğu temsil eder", body: "Bir kullanıcı isteği 10 farklı mikroservisten geçiyorsa, her biri kendi span'ini üretir; hepsi birleşince tek bir trace'i oluşturur — yavaşlığın hangi span'de olduğunu bulmak darboğazı tam olarak lokalize eder." },
  { id: "apm-09", category: "sik-sorun", title: "Alarm yorgunluğu (\"alert fatigue\") en büyük operasyonel risklerden biridir", body: "Çok fazla düşük-önemli alarm, gerçekten kritik olanın gözden kaçmasına yol açar — alarm eşiklerini iş etkisine göre önceliklendirmek (severity mapping), gürültüyü azaltmanın en etkili yoludur." },
  { id: "apm-10", category: "pratik-trick", title: "Instana/Dynatrace'te \"tag\" tabanlı filtreleme ekip bazlı görünüm sağlar", body: "Sunucular/servisler ortam (prod/test), takım veya uygulama etiketleriyle (tag) işaretlenirse, her ekip yalnızca kendi sorumluluğundaki metrikleri gören özelleştirilmiş bir dashboard oluşturabilir." },
  { id: "apm-11", category: "az-bilinen", title: "APM ajanının kendisi de CPU/bellek overhead'i yaratır", body: "Enstrümantasyon \"bedava\" değildir — tipik olarak %1-5 arası ek CPU yükü beklenir; çok yoğun, gecikmeye aşırı duyarlı sistemlerde bu overhead da kapasite planlamasına dahil edilmelidir." },
  { id: "apm-12", category: "efsane-gercek", title: "\"Log ve metrik aynı şeydir\" — YANLIŞ", body: "Metrik, zaman içindeki sayısal bir ölçümdür (örn. CPU %); log, belirli bir olayın metin kaydıdır. APM araçları ikisini birbirine bağlayarak (log'dan trace'e context) hızlı kök neden analizi sağlar, ama farklı veri türleridir." },

  // ── Linux / Networking ────────────────────────────────────────────────────
  { id: "net-01", category: "efsane-gercek", title: "\"ping çalışıyorsa sunucu tamamen sağlıklıdır\" — YANLIŞ", body: "ICMP (ping) yalnızca ağ katmanında bir yanıt olduğunu gösterir; hedef üzerindeki UYGULAMA (örn. port 8080'deki web servisi) çökmüş olsa bile ping çalışmaya devam edebilir." },
  { id: "net-02", category: "az-bilinen", title: "ss, netstat'ın modern ve daha hızlı yerine geçenidir", body: "`ss -tlnp` komutu, kernel'in soket bilgisine doğrudan (netlink üzerinden) erişir ve çok sayıda bağlantı olan sunucularda `netstat`'tan belirgin şekilde daha hızlı çalışır — çoğu modern dağıtımda netstat artık varsayılan olarak kurulu bile gelmeyebilir." },
  { id: "net-03", category: "pratik-trick", title: "dig +short ile hızlı DNS testi", body: "`dig +short example.com` yalnızca IP sonucunu döndürür, gürültülü tam çıktıyı atlar — script'lerde veya hızlı manuel kontrolde tercih edilir." },
  { id: "net-04", category: "sik-sorun", title: "\"Connection timed out\" ile \"Connection refused\" farklı katmanlarda oluşur", body: "\"Refused\" hedef makineye ulaşıldığını ama o portta hiçbir şeyin dinlemediğini gösterir (uygulama katmanı); \"timed out\" ise genelde bir güvenlik duvarının paketi sessizce düşürdüğünü (ağ katmanı) işaret eder." },
  { id: "net-05", category: "az-bilinen", title: "TCP'de 3'lü el sıkışma (SYN/SYN-ACK/ACK) her bağlantıda tekrar eder", body: "HTTP keep-alive kullanılmıyorsa, her istek için bu el sıkışma yeniden yapılır — yüksek gecikmeli ağlarda bu, algılanan yavaşlığın gizli bir sebebi olabilir." },
  { id: "net-06", category: "efsane-gercek", title: "\"DNS önbelleği asla yanlış olmaz\" — YANLIŞ", body: "TTL süresi dolmadan bir kayıt değiştirilirse, istemciler eski (stale) IP'yi kullanmaya devam eder — DNS değişikliği sonrası \"hala eski sunucuya gidiyor\" şikayetlerinin en yaygın nedeni budur." },
  { id: "net-07", category: "pratik-trick", title: "traceroute yerine mtr, sürekli/canlı rota analizi sağlar", body: "`mtr` (My TraceRoute), traceroute'un tek seferlik anlık görüntüsü yerine her hop için sürekli paket kaybı/gecikme istatistiği toplar — aralıklı (intermittent) ağ sorunlarını teşhis etmede çok daha güçlüdür." },
  { id: "net-08", category: "az-bilinen", title: "/etc/hosts, DNS sorgusundan ÖNCE kontrol edilir", body: "`nsswitch.conf`'taki varsayılan sıralama genelde `files dns` şeklindedir — bu yüzden `/etc/hosts`'a unutulmuş eski bir kayıt, güncel DNS'i görmezden gelerek sessizce yanlış IP'ye yönlendirebilir." },
  { id: "net-09", category: "sik-sorun", title: "MTU uyuşmazlığı büyük paketlerde sessiz veri kaybına yol açabilir", body: "Küçük istekler (ping, basit HTTP GET) çalışırken büyük dosya transferleri takılıyorsa, ağ yolundaki bir cihazın daha düşük MTU'su parçalanmayı (fragmentation) engelliyor olabilir — `ping -M do -s 1472` ile test edilir." },
  { id: "net-10", category: "pratik-trick", title: "curl -w ile detaylı zamanlama kırılımı", body: "`curl -w \"@format.txt\" -o /dev/null -s URL` ile DNS çözümleme, TCP bağlantı, TLS handshake ve ilk byte süresi (TTFB) ayrı ayrı ölçülebilir — yavaşlığın hangi aşamada olduğunu netleştirir." },
  { id: "net-11", category: "az-bilinen", title: "Bir portun \"LISTEN\" durumda olması, erişilebilir olduğu anlamına gelmez", body: "Servis 0.0.0.0 yerine yalnızca 127.0.0.1'de dinliyor olabilir, veya bir güvenlik duvarı kuralı dış erişimi engelliyor olabilir — `ss -tlnp` yerel dinlemeyi, harici bir test ise gerçek erişilebilirliği doğrular." },
  { id: "net-12", category: "efsane-gercek", title: "\"VPN'e bağlıyken her şey şifrelidir\" — Kısmen doğru", body: "VPN yalnızca istemci ile VPN ağ geçidi arasındaki trafiği şifreler; ağ geçidinden hedef sunucuya kadar olan iç trafik, ayrıca TLS kullanılmadıkça şifresiz kalabilir." },
  { id: "net-13", category: "pratik-trick", title: "tcpdump ile port bazlı hedefli paket yakalama", body: "`tcpdump -i eth0 port 443 -w capture.pcap` gibi filtreli bir yakalama, tüm trafiği kaydetmek yerine disk/performans yükünü azaltır ve ilgili trafiği doğrudan Wireshark'ta analiz etmeye hazır hale getirir." },
  { id: "net-14", category: "az-bilinen", title: "IPv6 devre dışı bırakılsa bile bazı servisler önce IPv6 dener", body: "Uygulama seviyesinde \"Happy Eyeballs\" veya eski getaddrinfo davranışı yüzünden, IPv6 route'u olmasa bile önce bir IPv6 denemesi yapılıp timeout beklenebilir — bu, açıklanamayan gecikmelerin gizli bir sebebidir." },
  { id: "net-15", category: "sik-sorun", title: "\"Intermittent\" (aralıklı) ağ sorunları genelde MTU, DNS round-robin veya load balancer health check'inden kaynaklanır", body: "Sürekli değil ama düzenli aralıklarla oluşan hatalar, tek bir kararlı arıza yerine birden fazla backend arasında dönen bir yük dengeleyicinin YALNIZCA BİRİNİN bozuk olmasından kaynaklanabilir." },

  // ── Log Analizi ────────────────────────────────────────────────────────────
  { id: "log-01", category: "pratik-trick", title: "grep -A/-B ile hata satırının bağlamını (context) görmek", body: "`grep -A 5 -B 2 \"ERROR\" server.log` yalnızca hata satırını değil, öncesindeki 2 ve sonrasındaki 5 satırı da gösterir — stack trace'in tamamını kaçırmadan hızlı inceleme sağlar." },
  { id: "log-02", category: "az-bilinen", title: "Log rotasyonu sırasında \"kayıp\" gibi görünen satırlar aslında yeni dosyaya taşınmıştır", body: "logrotate bir dosyayı yeniden adlandırıp yenisini oluşturduğunda, açık bir dosya tanıtıcısına (file descriptor) yazan bir process hâlâ ESKİ (artık adı değişmiş) dosyaya yazmaya devam edebilir — bu \"log kayboldu\" yanılgısının klasik sebebidir." },
  { id: "log-03", category: "efsane-gercek", title: "\"Hata logu yoksa sorun yoktur\" — YANLIŞ", body: "Birçok uygulama, sessizce yutulan (swallowed) istisnalar veya yanlış log seviyesi (DEBUG yerine hiç loglanmama) yüzünden kritik hataları göstermeyebilir — \"sessizlik\" bazen asıl alarm sinyalidir." },
  { id: "log-04", category: "pratik-trick", title: "journalctl -f --since ile canlı ve zaman filtreli log takibi", body: "`journalctl -u <servis> --since \"10 min ago\" -f` hem geçmiş 10 dakikayı gösterir hem de canlı akışa geçer — systemd tabanlı servislerde ayrı log dosyası aramaya gerek kalmaz." },
  { id: "log-05", category: "sik-sorun", title: "Zaman dilimi (timezone) uyuşmazlığı log korelasyonunu bozar", body: "Bir sunucu UTC, diğeri yerel saat dilimini kullanıyorsa, iki sistemin logları yan yana konduğunda olaylar gerçekte olmadığı sırada gerçekleşmiş gibi görünebilir — merkezi log toplamada tüm kaynakların tek bir zaman dilimine normalize edilmesi kritik önemdedir." },
  { id: "log-06", category: "az-bilinen", title: "Structured (JSON) loglar, düz metinden çok daha hızlı aranabilir", body: "Anahtar-değer çiftleri halinde yapılandırılmış loglar, Elasticsearch/Splunk gibi araçlarda regex yerine doğrudan alan bazlı (field-based) sorgulanabilir — bu, büyük ölçekte arama süresini saniyelerden milisaniyelere indirir." },
  { id: "log-07", category: "pratik-trick", title: "tail -f yerine less +F kesintisiz gezinme sağlar", body: "`less +F dosya.log` canlı takip modundayken Ctrl+C ile durdurulup dosyanın ESKİ kısımlarında gezinilebilir, sonra tekrar Shift+F ile canlı takibe dönülebilir — `tail -f`'te bu mümkün değildir." },
  { id: "log-08", category: "efsane-gercek", title: "\"WARN seviyesi önemsizdir, yok sayılabilir\" — Genelde YANLIŞ", body: "Birçok kritik olay (bağlantı havuzu tükenmeye yakın, deprecated API kullanımı, retry denemeleri) WARN seviyesinde loglanır — bir hata ERROR'a dönüşmeden ÖNCE genelde WARN'da ipucu bırakır." },
  { id: "log-09", category: "sik-sorun", title: "Disk dolduğunda uygulama log yazamaz ve sessizce davranış değiştirebilir", body: "Bazı uygulamalar disk dolu olduğunda logsuz çalışmaya devam eder, bazıları ise beklenmedik şekilde donar/çöker — \"aniden hiç log gelmiyor\" şikayeti çoğu zaman disk doluluğunu kontrol etmeyi gerektirir." },
  { id: "log-10", category: "pratik-trick", title: "awk ile log'dan yalnızca ihtiyaç duyulan sütunu çekmek", body: "`awk '{print $1, $4}' access.log` gibi bir komut, tüm satırı değil yalnızca IP ve zaman damgası gibi belirli alanları çıkarır — büyük access log'larda hızlı özetleme için grep+cut'tan daha esnektir." },

  // ── Genel Sistem Yönetimi / DevOps ─────────────────────────────────────────
  { id: "sys-01", category: "efsane-gercek", title: "\"Sunucuyu yeniden başlatmak her sorunu çözer\" — Kısa vadeli bir yanılsama", body: "Yeniden başlatma genelde semptomu (bellek sızıntısı, tıkanmış thread pool) geçici olarak gizler ama kök nedeni ORTADAN KALDIRMAZ — sorun, tetikleyici koşullar tekrar oluştuğunda geri döner." },
  { id: "sys-02", category: "pratik-trick", title: "df -i ile inode doluluğunu kontrol etmek", body: "`df -h` disk alanının dolu olmadığını gösterse bile, çok sayıda küçük dosya inode limitini tüketmiş olabilir — \"No space left on device\" hatası bazen boş görünen bir diskte bile inode tükenmesinden kaynaklanır." },
  { id: "sys-03", category: "az-bilinen", title: "Load average, yalnızca CPU kullanımını değil, I/O bekleyen process'leri de sayar", body: "Yüksek load average ile düşük CPU kullanımı bir arada görülüyorsa, darboğaz muhtemelen disk/ağ I/O'sudur, CPU değil — `vmstat` veya `iostat` ile ayırt edilmelidir." },
  { id: "sys-04", category: "sik-sorun", title: "\"Zombie\" process'ler CPU/bellek tüketmez ama process tablosunu doldurabilir", body: "Zombie process'ler zaten ölmüştür, yalnızca ebeveyninin `wait()` çağırmasını bekleyen bir process tablosu kaydıdır — çok sayıda birikirse yeni process oluşturmayı engelleyebilir (PID tükenmesi)." },
  { id: "sys-05", category: "pratik-trick", title: "systemctl status, son loglardan bir özet de gösterir", body: "`systemctl status <servis>` yalnızca aktif/pasif durumunu değil, journal'dan son birkaç log satırını da özetler — ayrı bir `journalctl` komutuna gerek kalmadan hızlı bir ilk bakış sağlar." },
  { id: "sys-06", category: "efsane-gercek", title: "\"Cron her zaman aynı ortam değişkenleriyle çalışır\" — YANLIŞ", body: "Cron, kullanıcının login shell'inden çok daha sınırlı bir ortamla (`PATH` dahil) çalışır — bir script terminalde çalışırken cron'da başarısız oluyorsa, genelde eksik/yanlış `PATH` veya ortam değişkeni sebebidir." },
  { id: "sys-07", category: "az-bilinen", title: "\"kill -9\" temizlik yapmaz, process'i anında keser", body: "SIGKILL (-9), process'e sinyali işleme veya kaynakları (açık dosyalar, geçici veriler) düzgünce kapatma şansı VERMEZ — mümkünse önce SIGTERM (-15) denenmeli, yalnızca yanıt vermiyorsa -9'a geçilmelidir." },
  { id: "sys-08", category: "sik-sorun", title: "\"Disk yok\" hatası bazen /tmp'nin dolmasından kaynaklanır", body: "Birçok uygulama geçici dosyalarını `/tmp`'ye yazar; bu bölüm ayrı bir mount noktasıysa ana disk boş görünse bile `/tmp` dolabilir ve uygulama beklenmedik şekilde hata verir." },
  { id: "sys-09", category: "pratik-trick", title: "top yerine htop, ağaç görünümü ve renk kodlamasıyla daha okunaklıdır", body: "`htop`, process ağacını (parent-child ilişkisini) görsel olarak gösterir ve F6 ile kolayca farklı sütuna göre sıralamaya izin verir — `top`'a göre canlı tanılamada daha hızlı bir deneyim sunar." },
  { id: "sys-10", category: "az-bilinen", title: "SELinux/AppArmor \"Permission denied\" hatası, dosya izinleri doğru olsa bile oluşabilir", body: "Standart Unix izinleri (rwx) doğru olsa bile, bir Mandatory Access Control (SELinux context/AppArmor profili) kısıtlaması işlemi engelleyebilir — `ausearch -m avc` veya `journalctl` ile SELinux denial'ları ayrıca kontrol edilmelidir." },
  { id: "sys-11", category: "efsane-gercek", title: "\"Yedekleme almak, geri yükleme testinin yerini tutar\" — YANLIŞ", body: "Düzenli olarak test edilmeyen bir yedek, gerçek bir felakette çalışmayabilir (bozuk dosya, eksik bağımlılık, süresi geçmiş kimlik bilgisi) — \"restore testi yapılmamış yedek yoktur\" prensibi klasik bir DevOps öğretisidir." },
  { id: "sys-12", category: "pratik-trick", title: "watch ile bir komutu periyodik tekrarlamak", body: "`watch -n 2 'oc get pods'` komutu, elle tekrar tekrar komut çalıştırmadan 2 saniyede bir güncellenen canlı bir görünüm sağlar — dağıtım/rollout izlerken çok kullanışlıdır." },
  { id: "sys-13", category: "sik-sorun", title: "Saat senkronizasyon (NTP) sapması dağıtık sistemlerde garip hatalara yol açar", body: "Sertifika doğrulama hataları, dağıtık kilitlerin (distributed lock) yanlış süresi dolması veya log korelasyon sorunları çoğu zaman kök nedeni saat kaymasıdır — `chronyc tracking` veya `timedatectl` ile kontrol edilir." },
  { id: "sys-14", category: "az-bilinen", title: "Bir dosya silinse bile açık tutan bir process varsa disk alanı boşalmaz", body: "`rm` bir dosyayı dizin listesinden kaldırır ama process hâlâ o dosyayı açık tutuyorsa (file descriptor), gerçek disk alanı process kapanana kadar serbest bırakılmaz — `lsof +L1` bu \"silinmiş ama açık\" dosyaları bulur." },

  // ── Yapay Zeka / LLM Okur-Yazarlığı ────────────────────────────────────────
  { id: "ai-01", category: "efsane-gercek", title: "\"AI Analist her zaman doğru cevap verir\" — YANLIŞ", body: "Büyük dil modelleri (LLM) bazen kendinden emin ama yanlış cevaplar üretebilir (\"hallucination\") — özellikle kritik bir karar öncesi, AI'ın önerdiği kök nedeni gerçek log/metrik verisiyle çapraz doğrulamak gerekir." },
  { id: "ai-02", category: "az-bilinen", title: "AI'a araç (tool) verildiğinde, hangi aracı çağıracağına kendisi karar verir", body: "Bu portaldaki AI Analist, kendisine tanımlanan playbook/API araçlarından hangisinin soruya uygun olduğuna prompt içindeki açıklamalara (description) bakarak karar verir — bu yüzden net ve spesifik sorular, daha isabetli araç seçimi sağlar." },
  { id: "ai-03", category: "pratik-trick", title: "AI'a ham log yerine özetlenmiş/filtrelenmiş veri vermek daha isabetli sonuç üretir", body: "Çok büyük, gürültülü bir log dökümü yerine ilgili zaman aralığına ve hata seviyesine filtrelenmiş bir alt küme paylaşmak, modelin dikkatinin gerçek soruna odaklanmasını sağlar." },
  { id: "ai-04", category: "efsane-gercek", title: "\"AI'a verdiğim veriler eğitim için kullanılıyor\" — Bu portalda kontrol edilebilir bir varsayım değil, doğrulanmalı", body: "Kurumsal AI entegrasyonlarında veri kullanım politikası sağlayıcıya göre değişir — hassas/kişisel veri paylaşmadan önce (PII maskeleme burada zaten otomatik uygulanıyor) her zaman kurumsal veri politikasına bakılmalıdır." },
  { id: "ai-05", category: "az-bilinen", title: "Bir AI aracının \"sessizce mevcut olmaması\" bilinçli bir tasarım kararı olabilir", body: "Bu portalda, yapılandırılmamış bir tanılama aracı (örn. template ID girilmemiş bir playbook) kullanıcıya hata göstermek yerine sohbette hiç görünmez — bu, \"kırık bir özellik göstermektense hiç gösterme\" prensibinin bilinçli bir uygulamasıdır." },
  { id: "ai-06", category: "pratik-trick", title: "AI Analist'e bağlam (context) vermek yanıt kalitesini doğrudan etkiler", body: "\"Sunucu yavaş\" yerine \"X sunucusunda saat 14:00'ten beri response time 3 kat arttı\" gibi somut, zaman/host belirten bir soru, modelin doğru aracı (Dynatrace/log/playbook) çağırmasını kolaylaştırır." },
  { id: "ai-07", category: "sik-sorun", title: "AI'ın önerdiği komutu kör kör çalıştırmak risklidir", body: "Özellikle yazma/değiştirme (write) yetkisi olan komutlarda, AI'ın önerisi bağlamı eksik veya güncel olmayan bir varsayıma dayanabilir — bu portaldaki tanılama araçlarının SALT-OKUNUR olması bilinçli bir güvenlik tercihidir." },
  { id: "ai-08", category: "az-bilinen", title: "LLM'ler \"düşünme\" değil, örüntü (pattern) tamamlama yapar", body: "Bir model doğru cevabı verdiğinde bile bu, insan gibi mantık yürütmekten değil, eğitim verisindeki benzer örüntülerin istatistiksel olarak en uygun devamını üretmekten kaynaklanır — bu, neden bazen çok emin ama yanlış olabildiğini açıklar." },

  // ── Sunucu/Envanter/Genel Portal Konuları ──────────────────────────────────
  { id: "inv-01", category: "pratik-trick", title: "Envanter verisini düzenli dışa aktarmak (CSV) denetim için altın standarttır", body: "Canlı bir veritabanı sorgusu yerine periyodik CSV dışa aktarımları, denetim (audit) sırasında \"belirli bir tarihte sistem hangi durumdaydı\" sorusuna kanıt sağlayan değişmez bir kayıt oluşturur." },
  { id: "inv-02", category: "az-bilinen", title: "Bir host'un envanterde \"aktif\" görünmesi, gerçekten erişilebilir olduğu anlamına gelmez", body: "Envanter kaydı genelde manuel veya periyodik senkronizasyonla güncellenir — LogX'teki \"Test Et\" adımı gibi canlı bir erişilebilirlik kontrolü, envanter kaydından bağımsız ayrı bir doğrulamadır." },
  { id: "inv-03", category: "sik-sorun", title: "Self Service kataloğunda \"az içerik\" uyarısı, admin'in henüz servis eklemediği anlamına gelir", body: "Bu bir hata değildir — kurumsal AWX şablonlarının self-service kataloğuna kaydı manuel bir admin adımı gerektirir, otomatik senkronize olmaz (bilinçli bir güvenlik/onay adımıdır)." },
  { id: "inv-04", category: "pratik-trick", title: "Nöbet çizelgesindeki \"yedek\" kişi, birincil nöbetçiye ulaşılamadığında aranmalıdır", body: "Yedek bilgisi süs değildir — birincil nöbetçinin dahili/telefonuna ilk denemede ulaşılamazsa, ikinci adım olarak yedek kişiye geçmek beklenen operasyonel akıştır." },
  { id: "inv-05", category: "az-bilinen", title: "LogX proxy bağlantıları merkezi audit log'una kaydedilir", body: "Bir sunucunun log servisine (port 1111) portal üzerinden erişildiğinde, bu erişim kim/ne zaman/hangi host bilgisiyle merkezi olarak loglanır — doğrudan SSH/RDP erişiminin aksine bu iz her zaman tutulur." },
  { id: "inv-06", category: "efsane-gercek", title: "\"Performance sayfasında sorun görünmüyorsa altyapı sağlıklıdır\" — Yanıltıcı olabilir", body: "Dynatrace bağlantısı koptuğunda (VPN/ağ erişimi sorunu) sayfa \"sorun yok\" değil \"veri yok\" durumunu gösterir — dashboard'daki \"DT Bağlantı Yok\" rozeti bu ayrımı yapmak için vardır, mutlaka kontrol edilmelidir." },

  { id: "misc-01", category: "az-bilinen", title: "\"HTTP 200 dönüyor\" her zaman isteğin başarılı olduğu anlamına gelmez", body: "Bazı API'ler hata durumunda bile HTTP 200 dönüp gerçek hata bilgisini yanıt gövdesinde (`{\"ok\": false, ...}`) taşır — yalnızca durum koduna bakmak yanıltıcı olabilir, gövde her zaman kontrol edilmelidir." },
  { id: "misc-02", category: "pratik-trick", title: "Bir problemi yeniden üretmeden ÖNCE zaman damgasını not almak, kök neden analizini hızlandırır", body: "\"Şu an yavaş\" yerine tam saat (ör. 14:32) not edilirse, o dakikaya ait log/metrik/trace verisi arasında kesin bir korelasyon kurulabilir — dakika bazında zaman damgası, saatlik özetten çok daha değerlidir." },
  { id: "misc-03", category: "efsane-gercek", title: "\"Prod'da test etmek her zaman kötüdür\" — Bağlama bağlı", body: "Salt-okunur, düşük riskli bir tanılama komutu (örn. bu portaldaki playbook'lar) production'da çalıştırılabilir çünkü sistem durumunu DEĞİŞTİRMEZ — riskli olan, test/staging'de doğrulanmamış YAZMA işlemlerini doğrudan production'da denemektir." },
  { id: "misc-04", category: "sik-sorun", title: "\"Bende çalışıyor\" sorunlarının çoğu ortam farkından kaynaklanır", body: "Farklı JVM sürümü, eksik ortam değişkeni, farklı işletim sistemi paket sürümü veya farklı ağ erişimi (VPN/firewall) — \"çalışıyor\" iddiasını doğrulamadan önce iki ortamın gerçekten aynı olduğunu teyit etmek gerekir." },
  { id: "misc-05", category: "az-bilinen", title: "Bir arıza bildirimi, olayın en son değil en ÖNCE ortaya çıktığı yer olmayabilir", body: "Kullanıcı önce arayüzde bir hata görür, ama kök neden birkaç katman aşağıda (veritabanı, ağ, üçüncü parti servis) olabilir — şikayetin geldiği katman, sorunun kaynağıyla aynı katman olmak zorunda değildir." },
];

