export const TECH_FACT_STATS = {
  baseCount: baseTechFacts.length,
  expandedCount: techFacts.length,
  multiplier: Number((techFacts.length / baseTechFacts.length).toFixed(1)),
};

export function getRandomTechFact(excludeId?: string): TechFact {
  const pool = excludeId ? techFacts.filter((f) => f.id !== excludeId) : techFacts;
  return pool[Math.floor(Math.random() * pool.length)];
}
